            rv = send_file(
                f,
                environ,
                mimetype=mimetype,
                download_name=real_filename,
                etag=self.generate_etag(mtime, file_size, real_filename),
                last_modified=mtime,
                max_age=self.cache_timeout,
            )
        except HTTPException as e:
            return e(environ, start_response)

        return rv(environ, start_response)

